// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 seed, address bystander) public {
        vm.assume(bystander != address(c));
        AirDropCaller caller = new AirDropCaller(c, seed);
        vm.assume(address(caller) != bystander);

        caller.go();

        // General rule: any caller that passes the supportsToken and hasNoBalance
        // checks and completes airDrop ends with exactly 20 tokens credited to itself,
        // and no other address's balance is touched.
        assertTrue(
            c.tokenBalance(address(caller)) == 20 && c.tokenBalance(bystander) == 0,
            "airDrop must credit 20 tokens to the successful caller"
        );
    }
}

// Adversarial counterparty: airDrop calls Bank(msg.sender).supportsToken(), so the
// caller must be a contract that returns the expected hash. This helper performs
// the airDrop on behalf of itself and answers the token check.
contract AirDropCaller {
    ModifierEntrancy public c;
    constructor(ModifierEntrancy target, uint256) { c = target; }
    function go() external { c.airDrop(); }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
